{"path": "/tmp/sv-c1dce98d254342c3bfb9fefd4ca1d2cf/Components/Pages/Board/TaskCard.razor", "file_text": "<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge @PriorityClass">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback MoveLeftClicked { get; set; }
    [Parameter] public EventCallback MoveRightClicked { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };

    private async System.Threading.Tasks.Task OnMoveLeft() => await MoveLeftClicked.InvokeAsync();
    private async System.Threading.Tasks.Task OnMoveRight() => await MoveRightClicked.InvokeAsync();
}
"}

{"path": "/tmp/sv-c1dce98d254342c3bfb9fefd4ca1d2cf/Components/Pages/Board/AddTaskForm.razor", "file_text": "<div class="add-task-form">
    <div class="form-group">
        <label>Title</label>
        <input type="text" @bind="Title" placeholder="Task title" />
    </div>
    <div class="form-group">
        <label>Assignee</label>
        <input type="text" @bind="Assignee" placeholder="Assignee name" />
    </div>
    <div class="form-group">
        <label>Priority</label>
        <select @bind="Priority">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
    </div>
    <div class="form-group">
        <label>Due Date</label>
        <input type="date" @bind="DueDate" />
    </div>
    <div class="form-actions">
        <button class="btn-save" @onclick="HandleSave">Save</button>
        <button class="btn-cancel" @onclick="HandleCancel">Cancel</button>
    </div>
</div>

@code {
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnSave { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private string Title { get; set; } = "";
    private string Assignee { get; set; } = "";
    private string Priority { get; set; } = "Medium";
    private DateTime DueDate { get; set; } = DateTime.Today;

    private async Task HandleSave()
    {
        if (!string.IsNullOrWhiteSpace(Title))
        {
            await OnSave.InvokeAsync((Title, Assignee, Priority, DueDate));
            Title = "";
            Assignee = "";
            Priority = "Medium";
            DueDate = DateTime.Today;
        }
    }

    private async Task HandleCancel() => await OnCancel.InvokeAsync();
}
"}

{"path": "/tmp/sv-c1dce98d254342c3bfb9fefd4ca1d2cf/Components/Pages/Board/KanbanColumn.razor", "file_text": "<div class="kanban-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="task-count">@Tasks.Count</span>
    </div>
    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      MoveLeftClicked="() => OnMoveLeft.InvokeAsync(task.Id)"
                      MoveRightClicked="() => OnMoveRight.InvokeAsync(task.Id)" />
        }
    </div>
    <div class="column-footer">
        @if (showForm)
        {
            <AddTaskForm OnSave="HandleTaskSave" OnCancel="HideForm" />
        }
        else
        {
            <button class="btn-add-task" @onclick="ShowForm">Add Task</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string ColumnName { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnAddTask { get; set; }

    private bool showForm;

    private void ShowForm() => showForm = true;
    private void HideForm() => showForm = false;

    private async Task HandleTaskSave((string Title, string Assignee, string Priority, DateTime DueDate) taskData)
    {
        await OnAddTask.InvokeAsync(taskData);
        showForm = false;
    }
}
"}

